'use strict';

/**
 * Least-recently-used cache with Map key semantics (SameValueZero).
 *
 * Recency is tracked by the insertion order of a private Map: the first
 * entry is the least recently used, the last is the most recently used.
 * Refreshing an entry is a delete + re-insert, so every operation is O(1).
 */
class LRUCache {
  #map = new Map();

  constructor(capacity) {
    if (typeof capacity !== 'number' || !Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError(`LRUCache capacity must be a positive integer, got ${String(capacity)}`);
    }
    this.capacity = capacity;
  }

  get(key) {
    const map = this.#map;
    if (!map.has(key)) return undefined;
    const value = map.get(key);
    map.delete(key);
    map.set(key, value);
    return value;
  }

  set(key, value) {
    const map = this.#map;
    if (map.has(key)) {
      map.delete(key);
    } else if (map.size >= this.capacity) {
      map.delete(map.keys().next().value);
    }
    map.set(key, value);
    return this;
  }

  has(key) {
    return this.#map.has(key);
  }

  delete(key) {
    return this.#map.delete(key);
  }

  get size() {
    return this.#map.size;
  }
}

module.exports = { LRUCache };

